import{_ as o,o as r,c as e,a2 as a}from"./chunks/framework.D0_YsCyK.js";const c=JSON.parse('{"title":"对接中转","description":"","frontmatter":{},"headers":[],"relativePath":"guide/relay.md","filePath":"guide/relay.md","lastUpdated":1794519054000}'),n={name:"guide/relay.md"};function d(s,t,l,i,g,h){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="对接中转" tabindex="-1">对接中转 <a class="header-anchor" href="#对接中转" aria-label="Permalink to &quot;对接中转&quot;">​</a></h1><p><strong>中转</strong> 页的 <strong>线路</strong> 标签按落地列出所有中转线路，点一个落地 → 选择隧道即可添加（也可以在落地页点入站 → <strong>中转</strong>）。隧道在 <strong>中转</strong> 页的 <strong>隧道</strong> 标签创建，入口是中转机；原来的“规则”在 <strong>规则</strong> 标签。隧道质量在 <strong>质量</strong> 标签查看。</p><h2 id="对接方式" tabindex="-1">对接方式 <a class="header-anchor" href="#对接方式" aria-label="Permalink to &quot;对接方式&quot;">​</a></h2><ul><li><strong>端口转发</strong>：中转机直接把流量转发到落地机的公网地址</li><li><strong>隧道转发（出口为落地机）</strong>：流量经隧道到落地机，再转发到 <code>127.0.0.1:入站端口</code>。入站可以只监听 <code>127.0.0.1</code>，落地机不对外暴露端口</li><li><strong>隧道转发（出口为其他节点）</strong>：用于“前置 → IX → 落地”这类多跳线路。流量经隧道到出口节点（如 IX），再由出口节点连接落地机的公网地址。只需要中转、不需要加密时，隧道协议选 TCP 即可</li></ul><h2 id="前置-→-ix-→-落地" tabindex="-1">前置 → IX → 落地 <a class="header-anchor" href="#前置-→-ix-→-落地" aria-label="Permalink to &quot;前置 → IX → 落地&quot;">​</a></h2><ol><li>节点页添加前置、IX、落地三台机器，都装好 agent</li><li>隧道页新建一条“隧道转发”：入口选前置，出口选 IX，协议按需选择（不需要加密就选 TCP）</li><li>点击落地机上的入站 → <strong>中转</strong>，选这条隧道</li><li>如果 IX 只允许前置访问，在 IX 的防火墙里放行前置的地址即可；落地机可以开启入站白名单，只放行 IX</li></ol><p>订阅里的中转线路使用前置的地址和入口端口。</p><h2 id="链中某一跳故障时-明确断开-不再静默绕行" tabindex="-1">链中某一跳故障时：明确断开，不再静默绕行 <a class="header-anchor" href="#链中某一跳故障时-明确断开-不再静默绕行" aria-label="Permalink to &quot;链中某一跳故障时：明确断开，不再静默绕行&quot;">​</a></h2><p>1.3.4 起，多跳链（隧道链 / 链式代理的节点侧链路）中<strong>任一跳的全部节点不可用时，连接会明确失败并报错</strong>（错误信息带链名，可定位是哪条链断了）：</p><ul><li>旧行为是中间跳故障时静默截断、绕过后面的跳继续走，首跳故障时甚至静默变成从本机<strong>直连</strong>出站——连接看似可用，实际出口与预期不符，还可能暴露真实出口 IP；</li><li>新行为下链部分故障期间受影响的连接直接断开，链恢复后自动正常；链健康时行为与之前完全一致。</li></ul><p>这是有意的行为变更：静默直连属于隐私事故，明确失败才可观测、可告警。如果升级后出现「链断了才发现某跳长期故障」，按报错里的链名检查对应跳的节点即可。</p><h2 id="订阅与清理" tabindex="-1">订阅与清理 <a class="header-anchor" href="#订阅与清理" aria-label="Permalink to &quot;订阅与清理&quot;">​</a></h2><p>中转线路会自动加入订阅，名称为“隧道名 → 入站名”。删除中转、入站或内核时，相关的转发会一并清理。</p><h2 id="隧道段端口的变更口径" tabindex="-1">隧道段端口的变更口径 <a class="header-anchor" href="#隧道段端口的变更口径" aria-label="Permalink to &quot;隧道段端口的变更口径&quot;">​</a></h2><p>一条隧道链上的端口分三类，变更口径完全不同，不要混读：</p><table tabindex="0"><thead><tr><th>段</th><th>是什么</th><th>编辑时口径</th></tr></thead><tbody><tr><td>入口段</td><td>转发在入口节点上的入口端口</td><td><strong>创建后永不变更</strong>：编辑转发时字段只读，绕过界面向接口提交现行行口集之外的值会被拒绝，见 <a href="./forward#入口端口创建后不可变更">端口转发 · 入口端口创建后不可变更</a></td></tr><tr><td>中段（链路）</td><td>链式隧道中间跳节点上的监听端口</td><td>编辑隧道保存时<strong>先沿用现口</strong>，现口失效才换（见下）</td></tr><tr><td>出口段</td><td>隧道出口节点上的监听端口</td><td>同中段</td></tr></tbody></table><p>中段 / 出口段的「换」不是随便换。在 <strong>中转</strong> 页 → <strong>隧道</strong> 标签 → 编辑隧道并保存时，系统对每个中段 / 出口段节点先沿用它在这条隧道里的现口；只有以下三种情况才给该段换到一个未被占用的端口：</p><ul><li>现口<strong>已被占用</strong>（被别的转发 / 入站 / 进程占了）；</li><li>现口<strong>不在该节点的端口范围内</strong>（例如之后改过该节点的端口范围）；</li><li>同一节点在这条隧道里<strong>改任另一段</strong>（原是链路跳、改成出口，或反之）：它在原段的端口不沿用到新段，按新段重新选未占用端口，同样会在回执里点名提示。</li></ul><p>前两种情况发生换口时，保存回执会逐条点名提示，形如「节点 &lt;节点名&gt; 出口端口由 20001 变更为 20007（原端口已被占用或不在节点端口范围内）」（中段显示为「链路端口」），前端逐条弹出；第三种情况（改任另一段）同样逐条点名，点名节点、新段与新旧端口。其余编辑——只改名、改其他与端口无关的项——不会动任何段的端口：现口只要还合法就沿用，不会因为保存了一次就漂移。新加入隧道的节点段（该节点原先不在这条隧道里）没有现口可沿用，按创建口径选未占用端口，不算换口、也没有点名提示。</p><p><strong>自检</strong>：编辑隧道只改名保存一次，回执里不应出现端口变更提示，各段端口应与保存前一致（在隧道与转发列表核对）；若出现点名提示，按提示里的节点名与新旧端口，去该节点核对端口占用与端口范围设置。</p><p>删隧道并把名下转发<strong>迁移</strong>到另一条隧道时，接口回执里还有一个 <code>portAdjustedCount</code> 字段，表示迁移中规范口被调整的转发条数。迁移按逐节点保留每条转发在各节点上的现口执行、不改任何一行的入口端口，该计数统计的是规范口（转发各行端口的最小值）层面的调整：保留下来的节点端口逐行不变时规范口不变、计数为 0；只有原最小口所在节点随源隧道退出、且目标隧道没有新增节点时，迁移后规范口会随行集变小被动上移，此时计数为 1——这是行集变化造成的被动漂移，不是把任何一行的端口改掉。看到 0 属正常，不是迁移没生效——迁移了多少条看回执的迁移条数（<code>migratedCount</code>）。</p><h2 id="链协议与-udp-承载、kcp-说明" tabindex="-1">链协议与 UDP 承载、KCP 说明 <a class="header-anchor" href="#链协议与-udp-承载、kcp-说明" aria-label="Permalink to &quot;链协议与 UDP 承载、KCP 说明&quot;">​</a></h2><p>链式隧道的每一段都可以独立选协议（TCP / TLS / MTLS / MTCP / WS / WSS / MWS / MWSS / UDP / KCP）。先说清一个容易误解的点：<strong>UDP 载荷的承载不依赖 KCP</strong>——无论段协议选哪一种，游戏、语音这类 UDP 流量都经隧道内置的帧化通道（FUDP）逐跳承载，选 TLS 段一样能跑 UDP。只有 KCP 是 <strong>UDP 原生传输</strong>：这一段的底层直接跑在 UDP 上，其余协议段的底层都是 TCP（或 WebSocket）。</p><p><strong>多跳建连时延（登录失败时先看这里）</strong>：链式隧道每条流、每一跳都是现拨一条新 TCP 连接并做一次 relay 握手，<strong>没有多路复用</strong>——同一条链上的多条流不共享连接，每跳的建连代价都会叠加。整条连接建立共用一个 <strong>15 秒总时限</strong>（不是每次尝试各 15 秒）：一次连接建立会在该总时限内自动重试，包括候选只有一个目标时；某次尝试快速失败（如被拒绝、被重置、解析失败或超时），剩余时间会结转给后续尝试继续用，尝试之间有短暂退避，总时限耗尽仍未建连才判失败。多候选时，后续尝试优先换到未失败的候选，候选都试过后才会回头重试已失败的候选。以下失败不重试、会立即报错，不会等满 15 秒、更不会无限重试：目标被安全守卫拒绝、调用方已取消本次连接、候选耗尽后仍无可用路由（空路由）。重试只发生在连接建立完成之前；连接一旦建立，后续流量不会重拨（与 server-first 类应用的首包处理不冲突）。server-first 应用（服务端先发首包，如部分游戏登录服）对多跳建连时延敏感：多跳建连慢或超时时，登录失败可能表现为约 15 秒后断开，或 2–5 秒量级的偶发超时，这是链路建连时延，不是单跳故障。</p><p>KCP 的定位与代价：</p><ul><li><p><strong>适合高丢包链路</strong>：KCP 自带快速重传与前向纠错（FEC），在丢包、抖动大的线路上，TCP 载荷的吞吐与延迟稳定性通常明显优于 TCP 段；干净链路上则没有优势，反而多付开销。</p></li><li><p><strong>FEC 开销约 +30%（缺省档）</strong>：FEC 缺省为 10 个数据片 + 3 个校验片，这一段腿上的实际带宽约为载荷的 1.3 倍（这部分开销计在节点侧，不计入用户的流量配额，用户配额只按入口载荷计一次）。FEC 可经配置键 <code>kcp_fec_mode</code> 整体关闭（见本节末尾配置键表），关后不再有这笔开销。</p></li><li><p><strong>窗口与缓冲按节点内存分档，模式与 MTU 仍固定</strong>：模式 fast3、MTU 1350 是固定值；但发送 / 接收窗口与缓冲<strong>不是固定值</strong>——按每个节点声明的内存分三档逐端下发（KCP 段两端各按本端节点的档位生成，窗口是逐端本地资源、不经协商，异档两端可正常互通）：</p><table tabindex="0"><thead><tr><th>档位</th><th>判定（该节点的声明内存）</th><th>发送 / 接收窗口</th><th>sockbuf / smuxbuf</th><th>streambuf</th><th>单会话最坏内存占用</th></tr></thead><tbody><tr><td>small（缺省）</td><td>未声明，或声明 ≤ 512MiB</td><td>512</td><td>1MiB / 1MiB</td><td>512KiB</td><td>约 4.8MiB</td></tr><tr><td>medium</td><td>声明 513–2048MiB</td><td>2048</td><td>2MiB / 2MiB</td><td>1MiB</td><td>约 12.3MiB</td></tr><tr><td>large</td><td>声明 &gt; 2048MiB（&gt; 2GiB）</td><td>4096</td><td>4MiB / 4MiB</td><td>2MiB</td><td>约 24.5MiB</td></tr></tbody></table><p><strong>窗口 4096 只对声明内存 &gt; 2GiB 的节点成立</strong>。面板拿不到节点总内存的可靠上报（agent 只报内存使用率），未声明的节点一律按 small 保守档下发——这是刻意的内存保护：旧口径窗口 / 缓冲全开时，单条忙 KCP 会话最坏可吃 10–25MiB，小内存节点多条 KCP 会话并发会先把内存打爆。在小内存节点上按 4096 窗口预期吞吐是达不到的，先按下面配置键给节点声明真实内存再看。</p></li><li><p><strong>加密按隧道自动生成</strong>：KCP 段启用 AES-256 加密，密钥由面板按隧道自动派生并同源下发到该段两端，不需要、也不能手工填写。注意升级口径：<strong>旧版本面板生成的 KCP 配置没有密钥，与新版本配置不互通</strong>——同一条 KCP 隧道的两端必须同批升级并重新下发配置后再用，混跑期间该段握手失败、整条隧道不通，这是预期行为，不是故障。</p></li></ul><p><strong>KCP 的两个配置键（管理员配置键，字段级）</strong>：上面分档与 FEC 档位由两个面板配置键驱动。两键都是敏感级配置键（仅管理员可读写），<strong>网站配置页暂无专用字段</strong>，经配置接口写入：管理员调用 <code>POST /api/v1/config/update-single</code>（请求体 <code>{&quot;name&quot;: &quot;&lt;键名&gt;&quot;, &quot;value&quot;: &quot;&lt;值&gt;&quot;}</code>），或用批量接口 <code>POST /api/v1/config/update</code> 一并提交。两键都在<strong>隧道配置生成时</strong>读取——改完键后，已有隧道要等其配置重新生成 / 重新下发才按新口径走（编辑保存该隧道即可触发），在途连接不受影响。</p><table tabindex="0"><thead><tr><th>配置键</th><th>可填值</th><th>未配置时</th><th>说明</th></tr></thead><tbody><tr><td><code>kcp_node_mem_mb</code></td><td>JSON 对象：键为节点 ID（十进制字符串）、值为该节点总内存 MiB，形如 <code>{&quot;12&quot;: 512, &quot;15&quot;: 4096}</code>；值须为 1–1048576 的整数</td><td>全部节点按 small 档</td><td>保存时整批校验：任一条目键不是合法节点 ID、或值越界，<strong>整批拒绝保存</strong>并点名原因，不会部分生效；填空值保存＝删除该键、回落未配置</td></tr><tr><td><code>kcp_fec_mode</code></td><td>只可填 <code>default</code> 或 <code>off</code></td><td><code>default</code>（10 数据片 + 3 校验片）</td><td><code>off</code>＝关闭 FEC（冗余归零，下发配置里不再出现数据片 / 校验片参数）；填其他值保存时直接报错拒绝；填空值保存＝删除该键、回落 <code>default</code></td></tr></tbody></table><p>防错警告：</p><ul><li><p><strong><code>kcp_node_mem_mb</code> 必须按机器真实总内存填</strong>。声明只决定参数档位、不校验机器真伪：往大填等于把该节点放回大档窗口 / 缓冲，多条 KCP 会话并发时按大档吃内存，小内存机器可能被打爆（OOM）——声明值由管理员对机器规格负责。拿不准就别声明，small 缺省档是安全侧。</p></li><li><p><strong><code>kcp_fec_mode</code> 是全局口径，不是逐隧道开关</strong>：设为 <code>off</code> 后所有 KCP 段都关 FEC。高丢包链路上关掉 FEC 会失去纠错冗余、吞吐与延迟稳定性明显下降；只在带宽成本压过丢包收益、且链路本身干净时才关。</p></li><li><p><strong>自检</strong>：保存配置键后，编辑任意一条含 KCP 段的隧道并保存（触发配置重新生成与下发），确认保存无报错、隧道恢复连通；再按上表拿节点声明内存对照其档位窗口——未声明节点窗口应为 512、声明 &gt; 2GiB 的节点应为 4096，对不上先查声明里节点 ID 写的是不是面板里的节点编号。</p></li><li><p><strong>质量页口径</strong>：KCP（及 UDP/QUIC）段在隧道质量里记「未测」、手动诊断里记「未验证」——UDP 没有通用回声协议可实测，这不代表该段不通，判通断以实际业务流量为准（见 <a href="./monitoring">监控</a>）。</p></li></ul><h2 id="限速规则-用户页" tabindex="-1">限速规则（用户页） <a class="header-anchor" href="#限速规则-用户页" aria-label="Permalink to &quot;限速规则（用户页）&quot;">​</a></h2><p><strong>限速规则</strong>（<strong>用户</strong> 页 → <strong>限速</strong> 标签）是命名的速率上限（名称 + 速率），建好后被引用才生效：</p><ul><li>转发可以分别绑一条<strong>全局限速</strong>（整条转发合计）和一条<strong>单 IP 限速</strong>（每个来源 IP 各一份）；</li><li>隧道本身不绑限速；在 <strong>用户</strong> 页把隧道分配给用户时，可以为这条分配选一条限速规则，该用户经这条隧道建立的转发按它限速（转发自己绑了全局限速时，以转发绑的为准）。</li></ul><h2 id="获取真实客户端-ip-仅-xray" tabindex="-1">获取真实客户端 IP（仅 Xray） <a class="header-anchor" href="#获取真实客户端-ip-仅-xray" aria-label="Permalink to &quot;获取真实客户端 IP（仅 Xray）&quot;">​</a></h2><p>开启后，中转转发会附带 PROXY protocol，落地机内核日志里能看到客户端真实 IP。开启后直连将无法使用，入站会自动变为“仅中转”。</p><h2 id="入站白名单" tabindex="-1">入站白名单 <a class="header-anchor" href="#入站白名单" aria-label="Permalink to &quot;入站白名单&quot;">​</a></h2><p>开启后，该入站端口只放行本机、直接连接落地机的节点（端口转发的中转机、隧道转发的出口节点）和你填写的额外 IP / 网段，其余来源直接丢弃，只影响这一个端口。中转增删时白名单会自动更新。节点级白名单开启时，以节点级为准，逐入站设置暂不生效（见下节）。</p><h2 id="节点级入站白名单" tabindex="-1">节点级入站白名单 <a class="header-anchor" href="#节点级入站白名单" aria-label="Permalink to &quot;节点级入站白名单&quot;">​</a></h2><p>与逐入站白名单同一机制、按节点开：默认关闭，在节点页为该节点开启后，该节点<strong>全部入站</strong>共用同一份白名单。填写的 IP / 网段用英文逗号分隔；除填写的地址外，只放行本机、直接连接该节点的节点（端口转发的中转机、隧道转发的出口节点），其余来源直接丢弃。</p><ul><li><strong>覆盖逐入站设置</strong>：节点级白名单开启时，以节点级为准，该节点各入站自己的白名单设置暂不生效。</li><li><strong>nftables 由 agent 自动安装（fail-closed）</strong>：白名单下发时 agent 会自检自装 nftables，用户不用手动装；装不上时内核 fail-closed 整体不启动（该内核全部入站下线），但面板会明示 nftables、节点与安装失败原因，不会静默。</li><li><strong>关键限制——要按客户端真实 IP 拦，必须开在入口机（第一跳）上</strong>：中转链路上，落地机看到的来源 IP 是中转机、不是客户端；在落地机上开白名单，只能拦中转机、拦不到客户端。想按客户端 IP 放行或拦截，把节点级白名单开在客户端先连到的那台入口机上。</li></ul><h2 id="删除隧道与节点离线时的语义" tabindex="-1">删除隧道与节点离线时的语义 <a class="header-anchor" href="#删除隧道与节点离线时的语义" aria-label="Permalink to &quot;删除隧道与节点离线时的语义&quot;">​</a></h2><p>删除隧道<strong>不需要节点在线</strong>：节点离线 / 不可达时，在面板里删隧道会立即生效——隧道、挂在它上面的转发与用户分配在数据库里一并删除，接口直接返回成功（对已删除的隧道重复删除同样返回成功），节点侧残留监听等重连对账时清理（见下）。一个例外形态：nftables 模式的转发在节点离线时删除会转入 pending-delete，这类转发记录有意以待清理形态保留、等后台对账确认节点侧规则已移除后才真正删掉（见 <a href="./forward">端口转发</a> 的删除口径），看到它残留不等于删隧道没删干净。</p><p>但有一个例外：<strong>节点在线、且删隧道前清理其名下转发的数据面时出现真实失败</strong>（节点明确回失败等非离线错误）时，删除会<strong>中止</strong>——隧道不会被删（防止留下脱离面板计数的孤儿监听），接口返回失败回执，并且回执会<strong>披露此前已实际删除的转发清单</strong>（已删除多少条、名称 / ID；已删项不回滚）。撞见这种回执时，先按回执里点名的转发与错误处理节点侧问题，再重新删隧道；不要按「离线也能删」的口径预期它必然成功。隧道与转发的手动诊断入口与结果口径见 <a href="./monitoring#手动诊断">监控 · 手动诊断</a>。</p><p>删除类接口有两种回执口径并存（有意设计）：<strong>单个删除</strong>（删隧道、删节点、删转发等）对「目标不存在」一律按已删处理、返回成功，重复删除与删后重试不会报错；<strong>批量删除、删除预览、连同转发一起删除</strong>这类复合操作则逐条给结论，目标不存在会明确报「隧道不存在」或计入失败明细，方便逐条对账。两种口径不要混读：单删的「成功」只承诺删完后该对象不存在，不承诺它删之前存在过。</p><p>节点侧监听的清理由 agent 在<strong>重连对账</strong>时完成：离线期间删掉的隧道，节点重新连上面板后会按面板的最新配置把对应监听撤掉，本机实测三方（数据库、节点监听、nft 规则）最终一致、无残留。</p><p>注意：如果节点其实没有停机、只是与面板<strong>网络分区</strong>（agent 还在运行、只是连不上），分区期间旧监听会继续按删除前的配置服务，直到分区恢复、agent 重连完成对账。介意这一点的场景，请先停掉节点 agent 再删隧道。</p>',46)])])}const u=o(n,[["render",d]]);export{c as __pageData,u as default};
